    def _make_suppressed(self, info):
        calls = []
        cond = threading.Condition()
        start = threading.Event()
        release = threading.Event()

        @cached(Cache(20), condition=cond, info=info)
        def f(k):
            calls.append(k)
            start.set()
            release.wait(5)
            return k

        return f, calls, start, release

    def test_same_key_stampede_suppression(self):
        for info in (False, True):
            with self.subTest(info=info):
                f, calls, start, release = self._make_suppressed(info)
                workers = [threading.Thread(target=lambda: f(4)) for _ in range(5)]
                try:
                    for w in workers:
                        w.start()
                    self.assertTrue(start.wait(2))
                    time.sleep(0.05)
                finally:
                    release.set()
                    for w in workers:
                        w.join(5)
                self.assertEqual(calls, [4])
                self.assertTrue(all(not w.is_alive() for w in workers))
                if info:
                    self.assertEqual(f.cache_info().misses, 1)
                    self.assertEqual(f.cache_info().hits, 4)

    def test_same_key_method_stampede_suppression(self):
        for info in (False, True):
            with self.subTest(info=info):
                calls = []
                cond = threading.Condition()
                start = threading.Event()
                release = threading.Event()

                class Owner:
                    def __init__(self):
                        self.cache = Cache(20)
                        self.cond = cond

                    @cachedmethod(
                        lambda self: self.cache,
                        condition=lambda self: self.cond,
                        info=info,
                    )
                    def run(self, k):
                        calls.append(k)
                        start.set()
                        release.wait(5)
                        return k

                owner = Owner()
                workers = [
                    threading.Thread(target=lambda: owner.run(4)) for _ in range(5)
                ]
                try:
                    for w in workers:
                        w.start()
                    self.assertTrue(start.wait(2))
                    time.sleep(0.05)
                finally:
                    release.set()
                    for w in workers:
                        w.join(5)
                self.assertEqual(calls, [4])
                self.assertTrue(all(not w.is_alive() for w in workers))

    def test_exception_cleanup(self):
        for info in (False, True):
            for method in (False, True):
                with self.subTest(info=info, method=method):
                    attempts = []
                    cond = threading.Condition()
                    if method:

                        class Owner:
                            def __init__(self):
                                self.cache = Cache(20)
                                self.cond = cond

                            @cachedmethod(
                                lambda self: self.cache,
                                condition=lambda self: self.cond,
                                info=info,
                            )
                            def run(self, k):
                                attempts.append(k)
                                if len(attempts) == 1:
                                    raise ValueError("original failure")
                                return k

                        f = Owner().run
                    else:

                        @cached(Cache(20), condition=cond, info=info)
                        def f(k):
                            attempts.append(k)
                            if len(attempts) == 1:
                                raise ValueError("original failure")
                            return k

                    with self.assertRaises(ValueError):
                        f(3)
                    # no deadlock, and the failed attempt did not poison the key
                    self.assertEqual(f(3), 3)
                    self.assertEqual(attempts, [3, 3])


class DistinctKeyConcurrencyTests(unittest.TestCase):
    def test_distinct_misses_compute_concurrently(self):
        for info in (False, True):
            for method in (False, True):
                with self.subTest(info=info, method=method):
                    h = _Harness(LRUCache(128), info, method, keys=("a", "b"))
                    ta = h.start("a")
                    tb = h.start("b")  # must be able to start while 'a' is held
                    self.assertEqual(sorted(h.calls[:2]), ["a", "b"])
                    h.finish(ta, tb)

    def test_interleaved_hit_while_pending(self):
        h = _Harness(LRUCache(128), info=False, method=False)
        h.f("other")  # warm
        holder = h.start("held")
        try:
            deadline = time.monotonic() + PROGRESS_TIMEOUT
            while h.f("other") != "value:other":
                self.assertLess(time.monotonic(), deadline)
            self.assertEqual(h.calls.count("other"), 0)
        finally:
            h.finish(holder)


