"""Stress / edge probing for the per-key pending fix."""

import random
import threading
import time

from cachetools import LRUCache, cached, cachedmethod

FAILS = []


def check(name, cond, detail=""):
    print(f"[{'ok' if cond else 'FAIL'}] {name} {detail}")
    if not cond:
        FAILS.append(name)


def stress(info, method, n_keys=8, n_threads=16, iters=40):
    cache = LRUCache(64)
    cond = threading.Condition()
    lock = threading.Lock()
    calls = {}
    bad = []

    def body(k):
        with lock:
            calls[k] = calls.get(k, 0) + 1
        time.sleep(random.uniform(0, 0.002))
        if k == "boom" and calls.get(k, 0) == 1:
            raise ValueError("first boom")
        return f"v:{k}"

    if method:

        class Owner:
            def __init__(self):
                self.cache = cache
                self.cond = cond

            @cachedmethod(
                lambda self: self.cache, condition=lambda self: self.cond, info=info
            )
            def run(self, k):
                return body(k)

        f = Owner().run
    else:
        f = cached(cache, condition=cond, info=info)(body)

    keys = [f"k{i}" for i in range(n_keys)] + ["boom"]

    def worker(seed):
        rnd = random.Random(seed)
        for _ in range(iters):
            k = rnd.choice(keys)
            try:
                v = f(k)
            except ValueError:
                continue
            if v != f"v:{k}":
                bad.append((k, v))

    threads = [threading.Thread(target=worker, args=(i,)) for i in range(n_threads)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(15)
    alive = [t for t in threads if t.is_alive()]
    check(
        f"stress info={info} method={method}: no deadlock",
        not alive,
        f"threads_alive={len(alive)} calls={sorted(calls.items())}",
    )
    check(f"stress info={info} method={method}: values correct", not bad, repr(bad[:3]))


def waiter_when_holder_raises():
    """A same-key waiter must proceed (recompute) when the holder fails."""
    for info in (False, True):
        for method in (False, True):
            cond = threading.Condition()
            entered = threading.Event()
            release = threading.Event()
            attempts = []

            def make_f():
                def body(k):
                    attempts.append(k)
                    entered.set()
                    release.wait(5)
                    if len(attempts) == 1:
                        raise ValueError("holder failure")
                    return k

                if method:

                    class Owner:
                        def __init__(self):
                            self.cache = LRUCache(8)
                            self.cond = cond

                        @cachedmethod(
                            lambda self: self.cache,
                            condition=lambda self: self.cond,
                            info=info,
                        )
                        def run(self, k):
                            return body(k)

                    return Owner().run
                return cached(LRUCache(8), condition=cond, info=info)(body)

            f = make_f()
            results = {}

            def holder():
                try:
                    f(9)
                except ValueError as e:
                    results["holder"] = repr(e)

            def waiter():
                try:
                    results["waiter"] = f(9)
                except ValueError as e:
                    results["waiter"] = f"waiter-raised {e!r}"

            t1 = threading.Thread(target=holder)
            t1.start()
            assert entered.wait(2)
            t2 = threading.Thread(target=waiter)
            t2.start()
            time.sleep(0.05)  # let the waiter block on the pending key
            release.set()
            t1.join(5)
            t2.join(5)
            check(
                f"waiter-with-failing-holder info={info} method={method}",
                not (t1.is_alive() or t2.is_alive())
                and results.get("waiter") == 9
                and results.get("holder", "").startswith("ValueError"),
                f"attempts={attempts} results={results}",
            )


def same_key_suppression_repeat():
    """Repeat suppression check many times to catch flakiness."""
    for info in (False, True):
        for r in range(5):
            calls = []
            cond = threading.Condition()
            release = threading.Event()
            start = threading.Event()

            @cached(LRUCache(4), condition=cond, info=info)
            def f(k):
                calls.append(k)
                start.set()
                release.wait(5)
                return k

            ws = [threading.Thread(target=lambda: f(1)) for _ in range(8)]
            for w in ws:
                w.start()
            assert start.wait(2)
            time.sleep(0.02)
            release.set()
            for w in ws:
                w.join(5)
            if calls != [1] or any(w.is_alive() for w in ws):
                check(f"suppression repeat info={info} run={r}", False, f"calls={calls}")
                return
    check("suppression repeat (10 runs)", True)


def main():
    random.seed(0)
    for info in (False, True):
        for method in (False, True):
            stress(info, method)
    waiter_when_holder_raises()
    same_key_suppression_repeat()
    print(f"\n{'ALL OK' if not FAILS else 'FAILURES: ' + repr(FAILS)}")
    return 1 if FAILS else 0


if __name__ == "__main__":
    raise SystemExit(main())

